-- Phonics · Blending section (Nov 18). Run only after the Blending private files are uploaded. Existing products are preserved.
-- The first three sheets are free; sheets 4 to 10 cost Rs 19. Every sheet has two pages: the sheet, then its answers.
on conflict (id) do nothing;
-- the Blending card on the Phonics board (there since Nov 3; this only makes sure it shows)
update public.sections set visible = true, group_id = 'phon', group_label = 'Phonics', updated_at = now() where id = 'blending';
-- check: should list pb-1 to pb-10, the first three with price 0
select id, price_inr, status from public.products where id like 'pb-%' order by sort;
